import { AppProvider } from "./context/AppContext";
import EarthViewer from "./components/EarthViewer";
import "./App.css"; // Re-enable this import
import styled from "styled-components";
import ControlPanel from "./components/ControlPanel"; // Add this import
import CountryInfo from "./components/CountryInfo"; // Add this import
import SettingsPanel from "./components/SettingsPanel"; // Add this import

const Overlay = styled.div`
  position: absolute;
  top: 20px;
  left: 20px;
  color: white;
  background: rgba(0, 0, 0, 0.5);
  padding: 8px;
  border-radius: 8px;
  z-index: 10;
`;

export default function App() {
  return (
    <AppStateProvider>
      <div
        style={{
          width: "100vw",
          height: "100vh",
          background: "#000011",
          position: "relative",
        }}
      >
        <EarthViewer />
        <Overlay>Styled Overlay</Overlay>
        <ControlPanel />
        <CountryInfo /> {/* Add this component */}
        <SettingsPanel /> {/* Add this component */}
      </div>
    </AppStateProvider>
  );
}
